pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        address target = address(new RevertingToken());
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);

        bool ok;
        try c.transfer(address(this), target, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Reference should revert due to inner call failing");
    }
}

contract RevertingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}
